import{_ as a,c as t,aU as e,a as o}from"./chunks/framework.DIXiA2XH.js";const u=JSON.parse('{"title":"金融相关","description":"","frontmatter":{},"headers":[],"relativePath":"note/knowledge/11-金融相关.md","filePath":"note/knowledge/11-金融相关.md","lastUpdated":1768740781000}'),r={name:"note/knowledge/11-金融相关.md"};function s(l,p,i,n,c,d){return o(),t("div",null,[...p[0]||(p[0]=[e('<h1 id="金融相关" tabindex="-1">金融相关 <a class="header-anchor" href="#金融相关" aria-label="Permalink to &quot;金融相关&quot;">​</a></h1><h2 id="什么是期货" tabindex="-1">什么是期货 <a class="header-anchor" href="#什么是期货" aria-label="Permalink to &quot;什么是期货&quot;">​</a></h2><p>比如你是爆米花的老板，需要买玉米，目前是1000元/吨，你担心三个月之后涨价，卖玉米的商家也担心三个月之后降价，所以你俩就签订了一份合约， 无论三个月后涨价还是降价，都以1000元/吨的价格交易，保证金10%，这份合约就是期货。</p><p>有了这份合约，你俩都抵消的风险。这就叫做 【套期保值】</p><p>这样看上去还挺好的 是吧？但是就是由于保证金制度和双向交易，使它成为了世界上最大的合法赌场。</p><div class="tip custom-block github-alert"><p class="custom-block-title">打个比方-保证金制度</p><p></p><p>如果你拿100元买股票，假如涨了10%，你就挣了10元。</p><p>如果你拿100元买期货（1000元/吨，保证金10%），假如涨了10%，也就是涨到了1100/吨，你就挣了100元。</p><p>这就是叫做【做多】</p><p>同样是100元本金，期货的盈亏就放大了10倍，这就是资本杠杆。</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">打个比方-双向交易</p><p></p><p>就是说，即使你没有玉米，你也可以卖玉米合约，假如你认为玉米会跌价，你可以用100元的保证金，先卖出去一份1000元/吨的玉米合约，等它跌到900的时候， 你再买过来交给对方，这下跌的100元就是你赚的，这就是叫做【做空】。</p></div><h2 id="什么是爆仓" tabindex="-1">什么是爆仓 <a class="header-anchor" href="#什么是爆仓" aria-label="Permalink to &quot;什么是爆仓&quot;">​</a></h2><p>所谓爆仓，是指在某些特殊条件下，投资者保证金账户中的客户权益为负值的情形，在虚拟货币、期货、外汇、股市等领域都会出现爆仓。</p><p>这里就要科普一个概念——保证金账户</p><p>保证金账户其实是一种信用账户。比如投资者可以用股票作抵押，按账户资产总市值的一定比例借用证券公司资金进行投资。特别是在股指期货交易中，为了确保履约，维护交易双方的合法权益，实行保证金交易制度。</p><p>通俗点说，你想投资购买一定的投资产品，但是手里的钱不够，于是你可以只拿出一部分钱，按照约定的比例存入保证金账户，其他的钱由平台替你出，并且收取一定的利息。</p><p>但是如果账户里的保证金变为负值，那就是爆仓了。但是爆仓跟钱亏光了还不一样，以比特币为例，如果爆仓了，那不止你的保证金账户的钱没了，购买的币也没了。</p><p><strong>为什么会爆仓</strong></p><p>为什么会保证金会变成负值？这就涉及到另一个概念——杠杆交易</p><p>所谓杠杆交易就是利用小额的资金来进行数倍于原始金额的投资。所以如果投资没有杠杆，就不会出现爆仓。</p><p>还是以比特币为例，假设你用1000美元加5倍的杠杆买了5000美元的比特币，相当于你投入了20%的保证金，如果第二天比特币上涨了20%，那手里的比特币价值就变成了6000美元，你挣了1000美元。但你的本金只有1000美元，所以相当于收益率100%。这就是杠杆交易。</p><p>但是如果反过来，第二天比特币跌了20%，那你就亏损了1000美元，相当于把本金亏没了。如果继续亏损，那平台借你的钱也要亏进去，所以平台就会强制把你的比特币卖掉，收回借你的钱和利息，这就是强行平仓。这样，你的钱没了，币也没了，连等它涨回去的机会都没有，也就是彻底爆仓了。</p><p>借来的钱是一个支点，放大了你的收益和损失，就像物理上的杠杆一样，所以叫“加杠杆”。</p><p>杠杆交易不止存在于虚拟货币领域，股票、期货交易中都是存在的，比特币之所以会有如此这样的高收益高亏损，就是因为它拥有高达125倍的杠杆。</p>',20)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
